// Fixed references were hand-calculated from nominal forces before importing
// the engine. They are not snapshots generated by the implementation.
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, resolve } from 'node:path';
import ts from 'typescript';
import { calculateSteelTension, STEEL_TENSION_METHOD_IDS, parse, evaluate, render } from '../packages/core/dist/index.js';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const templateText = readFileSync(resolve(root, 'packages/desktop/src/templates/steelTensionInternational.ts'), 'utf8');
const template = templateText.slice(templateText.indexOf('`') + 1, templateText.lastIndexOf('`'));
const reportSource = readFileSync(resolve(root, 'packages/desktop/src/lib/documentToReport.ts'), 'utf8')
  .replace('"@spanvision/calculations-core"', JSON.stringify(pathToFileURL(resolve(root, 'packages/core/dist/index.js')).href));
const reportModule = ts.transpileModule(reportSource, { compilerOptions: { target: ts.ScriptTarget.ES2020, module: ts.ModuleKind.ESNext } }).outputText;
const { documentToReport, projectToReport } = await import(`data:text/javascript;base64,${Buffer.from(reportModule).toString('base64')}`);
let assertions = 0;
function check(value, message) { assert.ok(value, message); assertions++; }
function close(actual, expected, message) { check(Math.abs(actual - expected) <= 1e-8 * Math.max(1, Math.abs(expected)), `${message}: ${actual} vs ${expected}`); }
const references = [
  // Ag=2000 mm², fy=250 MPa gives nominal gross yielding = 500 kN.
  // An=1600 mm², fu=410 MPa gives nominal net rupture = 656 kN.
  { id: 1, net: 1600, yield: 454.5454545454545, rupture: 472.32, governing: 'gross-section yielding' },
  { id: 2, net: 1600, yield: 450, rupture: 492, governing: 'gross-section yielding' },
  { id: 3, net: 1600, yield: 299.4011976047904, rupture: 328, governing: 'gross-section yielding' },
  { id: 4, net: 1600, yield: 500, rupture: 536.7272727272727, governing: 'gross-section yielding' },
  // Smaller net area = 1000 mm² gives nominal net rupture = 410 kN.
  { id: 1, net: 1000, yield: 454.5454545454545, rupture: 295.2, governing: 'net-section rupture' },
  { id: 2, net: 1000, yield: 450, rupture: 307.5, governing: 'net-section rupture' },
  { id: 3, net: 1000, yield: 299.4011976047904, rupture: 205, governing: 'net-section rupture' },
  { id: 4, net: 1000, yield: 500, rupture: 335.4545454545454, governing: 'net-section rupture' },
];
const inputFor = (row) => ({ method: STEEL_TENSION_METHOD_IDS[row.id], grossAreaMm2: 2000, netAreaMm2: row.net, yieldStrengthMPa: 250, ultimateStrengthMPa: 410, requiredTensionKN: 300 });
const valuesFor = (row) => ({ tension_method: String(row.id), tension_Ag: '2000', tension_An: String(row.net), tension_fy: '250', tension_fu: '410', tension_N: '300' });
function assignments(nodes, target = {}) { for (const n of nodes) { if (n.type === 'assignment') target[n.name] = Number(n.result); if (n.type === 'conditional-branch') assignments(n.children, target); } return target; }
const sheets = [];
for (const row of references) {
  const expectedCapacity = Math.min(row.yield, row.rupture);
  const result = calculateSteelTension(inputFor(row));
  close(result.yieldingCapacityKN, row.yield, `method ${row.id} yielding`);
  close(result.ruptureCapacityKN, row.rupture, `method ${row.id} rupture`);
  close(result.sectionCapacityKN, expectedCapacity, 'governing capacity');
  close(result.utilization, 300 / expectedCapacity, 'utilization');
  check(result.governingLimitState === row.governing, 'governing limit state');
  check(result.sectionWithinCapacity === (300 <= expectedCapacity), 'overloaded ASD/Indian rupture correctly fails');
  check(result.completeMemberVerification === false, 'never claim a complete member verification');
  const nodes = evaluate(parse(template), valuesFor(row), { K_FI: 999, CC: 3, rekenwijze: 1 });
  const numeric = assignments(nodes);
  // Assignment results are display strings (four significant digits), while
  // engine values and machine-readable report evidence retain full precision.
  close(numeric.tension_Ry, Number(row.yield.toPrecision(4)), 'displayed report yielding');
  close(numeric.tension_Ru, Number(row.rupture.toPrecision(4)), 'displayed report rupture');
  close(numeric.tension_R, Number(expectedCapacity.toPrecision(4)), 'displayed report capacity');
  const html = render(nodes);
  check(html.includes('Complete member verification remains outstanding'), 'human output retains scope');
  check(!html.includes('calc-error'), 'no evaluation/render error');
  const report = documentToReport(nodes, `Method ${row.id}`);
  const exported = report.metadata.engineering_checks[0];
  close(exported.sectionCapacityKN, expectedCapacity, 'machine report capacity');
  check(exported.input.method === result.input.method && exported.standard.edition === result.standard.edition, 'report records exact standard/method');
  check(JSON.stringify(report).includes('Excluded checks') && exported.excludedChecks.includes('connection and block shear'), 'human and machine reports retain exclusions');
  sheets.push({ naam: `Method ${row.id}, An ${row.net}`, nodes });
}
const baseline = inputFor(references[0]);
const invalid = [
  { method: 'NL' }, { grossAreaMm2: 0 }, { netAreaMm2: 0 }, { netAreaMm2: 2001 },
  { grossAreaMm2: -1 }, { netAreaMm2: NaN }, { yieldStrengthMPa: Infinity },
  { yieldStrengthMPa: 99 }, { yieldStrengthMPa: 701 }, { ultimateStrengthMPa: 249 },
  { ultimateStrengthMPa: 1001 }, { requiredTensionKN: -1 }, { requiredTensionKN: NaN },
  { grossAreaMm2: '2000' }, { grossAreaMm2: Number.MAX_VALUE }, { netAreaMm2: Number.MIN_VALUE },
];
for (const override of invalid) { assert.throws(() => calculateSteelTension({ ...baseline, ...override })); assertions++; }
for (const malformed of ['', '0', '-1', 'Infinity', 'NaN', '12abc', '2 * 1000', '<script>']) {
  const nodes = evaluate(parse(template), { ...valuesFor(references[0]), tension_Ag: malformed });
  const html = render(nodes);
  check(html.includes('Invalid inputs'), `malformed raw input ${JSON.stringify(malformed)} rejected`);
  check(!('tension_R' in assignments(nodes)), 'invalid input produces no capacity');
  check(!html.includes('Cross-section within capacity'), 'invalid input cannot print apparent pass');
  check(documentToReport(nodes, 'Invalid').metadata.engineering_checks[0].valid === false, 'invalidity is machine-readable');
}
const exact = calculateSteelTension({ ...baseline, method: 'US-AISC360-22-LRFD', requiredTensionKN: 450 });
check(exact.sectionWithinCapacity && exact.utilization === 1, 'exact capacity boundary accepted');
check(!calculateSteelTension({ ...exact.input, requiredTensionKN: 450.0001 }).sectionWithinCapacity, 'just-over capacity rejected');
check(calculateSteelTension({ ...baseline, requiredTensionKN: 0 }).utilization === 0, 'zero demand allowed');
const project = projectToReport(sheets, 'International steel tests');
check(project.metadata.engineering_checks.length === 8, 'all independent sheet records exported');
check(project.metadata.engineering_checks.every((n) => n.sheet && n.completeMemberVerification === false), 'project metadata retains sheet provenance and scope');
const output = { checkedAt: new Date().toISOString(), status: 'passed', assertions, referenceCases: references.length, methods: Object.values(STEEL_TENSION_METHOD_IDS), scope: 'Two cross-section limit states only; external engineering review and current AISC errata review pending.' };
const evidenceDir = resolve(root, '../qa/readiness/standards');
mkdirSync(evidenceDir, { recursive: true });
writeFileSync(resolve(evidenceDir, 'steel-tension-reference-results.json'), `${JSON.stringify(output, null, 2)}\n`);
console.log(JSON.stringify(output, null, 2));
